import type { PlaceRoutability, PlaceType } from "../../lib/easyt/place-intelligence.ts";
import type { SemanticTransportMode } from "../../lib/easyt/semantic-trip-intent.ts";

export const GLOBAL_ROUTING_BENCHMARK_VERSION = "global-routing/v1" as const;

export type GlobalRoutingRegion =
  | "central-america" | "south-america" | "north-america" | "western-europe"
  | "balkans" | "scandinavia" | "uk-ireland" | "north-africa"
  | "southern-africa" | "east-africa" | "middle-east" | "central-asia"
  | "india-nepal" | "southeast-asia" | "china" | "japan" | "korea"
  | "indonesia" | "australia-new-zealand" | "pacific";

export type BenchmarkPlace = {
  key: string;
  sourceText: string;
  canonicalName: string;
  country: string;
  coordinates?: [number, number];
  placeType: PlaceType;
  routability: PlaceRoutability;
  semanticRole: "route-stop" | "planning-area" | "anchor" | "ambiguous" | "unresolved";
  interpretedText?: string;
  ambiguityCandidates?: Array<{
    canonicalName: string;
    country: string;
    coordinates: [number, number];
    placeType: PlaceType;
    routability: PlaceRoutability;
  }>;
};

export type GlobalRoutingFixture = {
  id: string;
  name: string;
  region: GlobalRoutingRegion;
  p0?: boolean;
  prompt: string;
  origin: BenchmarkPlace | null;
  originAlsoOvernight?: boolean;
  destinations: BenchmarkPlace[];
  routeOrder: string[];
  expectedAmbiguities: string[];
  anchorBaseRelationships: Array<{ anchorKey: string; baseKey?: string }>;
  semantic: {
    interStop?: { sourceText: string; modes: SemanticTransportMode[] };
    departure?: { sourceText: string; mode: SemanticTransportMode };
    avoid?: Array<{ sourceText: string; mode: SemanticTransportMode }>;
    pace?: { sourceText: string; value: "relaxed" | "balanced" | "packed" };
    interests?: Array<{ sourceText: string; value: "food" | "coast" | "nightlife" | "culture" | "nature" | "adventure" | "shopping" | "wellness" | "other" }>;
    forbiddenGeographyTerms: string[];
  };
  knownTransportHardConstraints: string[];
  requiredUnknownLegs?: string[];
  recordedConnections?: Array<{
    fromKey: string;
    toKey: string;
    mode: "flight" | "train" | "road" | "ferry" | "unknown";
    planningMinutes: number | null;
  }>;
  forbiddenModesByLeg?: Record<string, Array<"flight" | "train" | "road" | "ferry" | "walk" | "unknown">>;
  allowedUncertainty: string[];
  forbiddenOutcomes: string[];
  crossSurface?: boolean;
};

type PlaceOptions = Partial<Pick<BenchmarkPlace, "placeType" | "routability" | "semanticRole" | "interpretedText" | "ambiguityCandidates">>;

const place = (
  key: string,
  sourceText: string,
  canonicalName: string,
  country: string,
  coordinates: [number, number] | undefined,
  options: PlaceOptions = {},
): BenchmarkPlace => ({
  key,
  sourceText,
  canonicalName,
  country,
  coordinates,
  placeType: options.placeType ?? "city",
  routability: options.routability ?? "direct_destination",
  semanticRole: options.semanticRole ?? "route-stop",
  interpretedText: options.interpretedText,
  ambiguityCandidates: options.ambiguityCandidates,
});

const city = (key: string, source: string, name: string, country: string, coordinates: [number, number], options: PlaceOptions = {}) =>
  place(key, source, name, country, coordinates, options);
const town = (key: string, source: string, name: string, country: string, coordinates: [number, number], options: PlaceOptions = {}) =>
  place(key, source, name, country, coordinates, { placeType: "town", ...options });
const anchor = (key: string, source: string, name: string, country: string, coordinates: [number, number], placeType: PlaceType = "landmark") =>
  place(key, source, name, country, coordinates, { placeType, routability: "needs_base_selection", semanticRole: "anchor" });
const region = (key: string, source: string, name: string, country: string, coordinates?: [number, number], placeType: PlaceType = "region") =>
  place(key, source, name, country, coordinates, { placeType, routability: "planning_area", semanticRole: "planning-area" });
const island = (key: string, source: string, name: string, country: string, coordinates: [number, number], direct = false) =>
  place(key, source, name, country, coordinates, { placeType: "island", routability: direct ? "direct_destination" : "needs_base_selection", semanticRole: direct ? "route-stop" : "planning-area" });
const ambiguous = (key: string, source: string, candidates: NonNullable<BenchmarkPlace["ambiguityCandidates"]>) =>
  place(key, source, source, "", undefined, { placeType: "unknown", routability: "non_routable_reference", semanticRole: "ambiguous", ambiguityCandidates: candidates });
const country = (key: string, source: string, name: string) =>
  place(key, source, name, name, undefined, { placeType: "country", routability: "planning_area", semanticRole: "planning-area" });

const sharedForbidden = [
  "Drop a requested destination or unresolved destination intention.",
  "Insert an unrelated city or replace a country/anchor with its capital.",
  "Present unsupported transport timing, availability or fares as confirmed.",
];

const fixture = (value: Omit<GlobalRoutingFixture, "knownTransportHardConstraints" | "allowedUncertainty" | "forbiddenOutcomes"> & Partial<Pick<GlobalRoutingFixture, "knownTransportHardConstraints" | "allowedUncertainty" | "forbiddenOutcomes">>): GlobalRoutingFixture => ({
  ...value,
  knownTransportHardConstraints: value.knownTransportHardConstraints ?? [],
  allowedUncertainty: value.allowedUncertainty ?? ["Live schedules, border conditions and fares may remain unknown."],
  forbiddenOutcomes: [...sharedForbidden, ...(value.forbiddenOutcomes ?? [])],
});

